function dump(n, depth) {
  let s = "  ".repeat(depth) + n.name + " [" + n.type + "]";
  if (n.type === "TEXT") {
    s += " chars=" + JSON.stringify(n.characters) + " font=" + (n.fontName !== figma.mixed ? n.fontName.family + "/" + n.fontName.style : "mixed") + " size=" + (n.fontSize !== figma.mixed ? n.fontSize : "mixed") + " fills=" + JSON.stringify(n.fills !== figma.mixed ? n.fills : "mixed");
  } else if ("fills" in n && n.fills !== figma.mixed && n.fills.length) {
    s += " fills=" + JSON.stringify(n.fills.map(f => f.type === "SOLID" ? f.color : f.type));
  }
  if ("cornerRadius" in n && n.cornerRadius !== figma.mixed) s += " r=" + n.cornerRadius;
  if ("strokes" in n && n.strokes && n.strokes.length) s += " strokes=" + JSON.stringify(n.strokes.map(f=>f.type==="SOLID"?f.color:f.type)) + " sw=" + n.strokeWeight;
  if ("layoutMode" in n && n.layoutMode !== "NONE") s += " layout=" + n.layoutMode + " gap=" + n.itemSpacing + " pad=" + [n.paddingLeft,n.paddingRight,n.paddingTop,n.paddingBottom].join(",");
  if ("children" in n && depth < 3) for (const c of n.children) s += "\n" + dump(c, depth+1);
  return s;
}
const out = [];
for (const id of ["2:24","2:29","2:34","2:45"]) {
  const n = await figma.getNodeByIdAsync(id);
  out.push(dump(n, 0));
}
return out.join("\n---\n");

