function fillCard(inst, o){
  const img=inst.findOne(n=>n.name==="Image");
  const np=inst.findOne(n=>n.name==="NoPhoto");
  if(o.media){
    const src=MEDIA[o.media];
    img.fills=JSON.parse(JSON.stringify(src.fills));
    if(np) np.visible=false;
  } else {
    img.fills=[{type:"SOLID",color:{r:0.95,g:0.95,b:0.96}}];
    if(np) np.visible=true;
  }
  const nm=inst.findOne(n=>n.name==="Name");
  if(nm){nm.characters=o.name;}
  const d=inst.findOne(n=>n.name==="Desc");
  if(d){ if(o.desc){d.characters=o.desc;d.visible=true;} else {d.visible=false;} }
  const pr=inst.findOne(n=>n.name==="Price"); if(pr)pr.characters=o.price;
  const wa=inst.findOne(n=>n.name==="Was"); if(wa)wa.characters=o.was;
  const of=inst.findOne(n=>n.name==="Off"); if(of)of.characters=o.off;
  const rc=inst.findOne(n=>n.name==="RatingCount"); if(rc)rc.characters=o.rating;
}

